              title={`Alerjenler: ${product.allergens.join(', ')}`}
            >
              Alerjen
            </span>
          )}
        </div>
        <div className="mt-0.5 flex items-center gap-2 text-xs text-secondary-500 dark:text-secondary-400">
          {product.category && (
            <span className="truncate">{product.category.name}</span>
